hooks.command:
command -v jq >/dev/null 2>&1 || { echo "ogxo-format: jq not found; this hook is inactive. Install jq to enable it." >&2; exit 1; }; f=$(jq -r '.tool_input.file_path // empty'); [ -n "$f" ] && [ -f "$f" ] || exit 0; case "$f" in *.js|*.jsx|*.ts|*.tsx|*.json|*.css|*.scss|*.md|*.html|*.yaml|*.yml) npx --no-install prettier --write "$f" >/dev/null 2>&1 || true ;; *.go) gofmt -w "$f" 2>/dev/null || true ;; *.rs) rustfmt "$f" 2>/dev/null || true ;; *.py) black --quiet "$f" 2>/dev/null || true ;; esac; problems=''; case "$f" in *.md|*.markdown|*.diff|*.patch) ;; *) lines=$(grep -nE '[[:blank:]]+$' "$f" 2>/dev/null | head -5); [ -n "$lines" ] && problems="Trailing whitespace in $f — remove it (line:content): $(printf '%s' "$lines" | tr '\n' ' ')" ;; esac; case "$f" in *.yml|*.yaml) if python3 -c 'import yaml' 2>/dev/null; then err=$(python3 -c 'import sys,yaml
try:
    list(yaml.compose_all(open(sys.argv[1]), Loader=yaml.SafeLoader))
except yaml.YAMLError as e:
    print(e); sys.exit(1)' "$f" 2>&1) || problems="${problems:+$problems
}YAML syntax error in $f: $err"; fi ;; esac; [ -z "$problems" ] || { printf '%s\n' "$problems" >&2; exit 2; }
